package service

import("testing";"github.com/google/uuid";"github.com/onoja217/users-management-app/internal/authz";"github.com/onoja217/users-management-app/internal/models";"github.com/onoja217/users-management-app/internal/repository";"gorm.io/driver/sqlite";"gorm.io/gorm")
func TestGuardianRelationshipAccess(t *testing.T){db,err:=gorm.Open(sqlite.Open("file:guardian_test?mode=memory&cache=shared"),&gorm.Config{});if err!=nil{t.Fatal(err)};if err=db.AutoMigrate(&models.User{},&models.Student{},&models.AcademicSession{},&models.Term{},&models.SchoolClass{},&models.Section{},&models.StudentEnrollment{},&models.AttendanceRecord{},&models.Assessment{},&models.AssessmentResult{},&models.TeacherAssignment{},&models.Subject{},&models.TimetableEntry{},&models.Invoice{},&models.InvoiceLine{},&models.Payment{},&models.GuardianRelationship{});err!=nil{t.Fatal(err)};g:=models.User{Name:"Parent",Email:"p@test",Role:authz.RoleParent,Active:true};other:=models.User{Name:"Other",Email:"o@test",Role:authz.RoleParent,Active:true};st:=models.User{Name:"Student",Email:"s@test",Role:authz.RoleStudent,Active:true};for _,u:=range []*models.User{&g,&other,&st}{if err=db.Create(u).Error;err!=nil{t.Fatal(err)}};student:=models.Student{UserID:st.ID,AdmissionNumber:"ADM-1"};if err=db.Create(&student).Error;err!=nil{t.Fatal(err)};rel:=repository.NewGuardianRepository(db);if _,err=rel.Create(models.GuardianRelationship{GuardianUserID:g.ID,StudentID:student.ID,Relationship:"mother",Active:true});err!=nil{t.Fatal(err)};svc:=NewGuardianService(rel,db);if _,err=svc.Children(g.ID);err!=nil{t.Fatal(err)};if _,err=svc.Attendance(other.ID,student.ID);err!=ErrGuardianForbidden{t.Fatalf("expected forbidden, got %v",err)};if _,err=svc.CreateLink(other.ID,student.ID,"father",false);err!=nil{t.Fatal(err)};if _,err=svc.CreateLink(g.ID,student.ID,"duplicate",false);err!=ErrGuardianInvalid{t.Fatalf("expected duplicate rejection, got %v",err)};_ = uuid.Nil}
